code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    row_groups = []
    start = 0
    for r in range(h):
        if r in sep_rows:
            if start < r:
                row_groups.append(range(start, r))
            start = r + 1
    if start < h:
        row_groups.append(range(start, h))
    col_groups = []
    start = 0
    for c in range(w):
        if c in sep_cols:
            if start < c:
                col_groups.append(range(start, c))
            start = c + 1
    if start < w:
        col_groups.append(range(start, w))
    counts = Counter(grid[r][c] for rows in row_groups for r in rows for cols in col_groups for c in cols)
    background = counts.most_common(1)[0][0]
    out = []
    for rows in row_groups:
        outrow = []
        for cols in col_groups:
            marks = [(ri, ci) for ri, r in enumerate(rows) for ci, c in enumerate(cols) if grid[r][c] != background]
            interior_single = len(marks) == 1 and 0 < marks[0][0] < len(rows)-1 and 0 < marks[0][1] < len(cols)-1
            outrow.append(1 if len(marks) >= 2 or interior_single else background)
        out.append(outrow)
    return out
'''
